import boto3

def moderate_transcript(transcript_text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[
            {
                'Text': transcript_text
            }
        ],
        LanguageCode='en'
    )
    toxic_content = response['ToxicContent']
    if toxic_content:
        print('Toxic content detected: ', toxic_content)
        return False
    else:
        print('No toxic content detected.')
        return True

if __name__ == '__main__':
    sample_transcript = 'This is a sample transcript text.'
    if moderate_transcript(sample_transcript):
        print('Transcript is ready for publishing.')
    else:
        print('Transcript needs moderation before publishing.')

from google.cloud import speech_v1 as speech

def create_transcription_request(audio_uri, config):
    return speech.types.TranscriptionConfig(audio=speech.types.Audio(uri=audio_uri), config=config)

def parse_transcription_response(response):
    results = []
    for result in response.results:
        alternatives = []
        for alternative in result.alternatives:
            alternatives.append({
                'transcript': alternative.transcript,
                'confidence': alternative.confidence
            })
        results.append({
            'alternatives': alternatives,
            'channel_tag': result.channel_tag
        })
    return results

def normalize_transcription_results(results):
    normalized_results = []
    for result in results:
        normalized_alternatives = []
        for alternative in result['alternatives']:
            normalized_alternatives.append({
                'transcript': alternative['transcript'].lower().strip(),
                'confidence': alternative['confidence']
            })
        normalized_results.append({
            'alternatives': normalized_alternatives,
            'channel_tag': result['channel_tag']
        })
    return normalized_results

import boto3

def get_timestamped_transcript(transcription_job_name):
    transcribe = boto3.client('transcribe')
    response = transcribe.get_transcription_job(TranscriptionJobName=transcription_job_name)

    if response['TranscriptionJob']['TranscriptionJobStatus'] == 'COMPLETED':
        transcript_uri = response['TranscriptionJob']['Transcript']['TranscriptFileUri']
        transcript_response = transcribe.get_transcription_job(TranscriptionJobName=transcription_job_name)
        transcript = transcript_response['TranscriptionJob']['Transcript']['TranscriptFileUri']

        # Fetch the transcript content
        import requests
        transcript_content = requests.get(transcript).json()

        # Extract timestamps
        timestamped_transcript = {}
        for item in transcript_content['results']['items']:
            if 'start_time' in item and 'end_time' in item:
                timestamped_transcript[item['alternatives'][0]['content']] = {
                    'start_time': item['start_time'],
                    'end_time': item['end_time']
                }
        return timestamped_transcript
    else:
        return 'Transcription job is not completed.'

import boto3

def poll_transcription_job(job_name):
    transcribe = boto3.client('transcribe')
    while True:
        job = transcribe.get_transcription_job(TranscriptionJobName=job_name)
        job_status = job['TranscriptionJob']['TranscriptionJobStatus']
        if job_status in ['COMPLETED', 'FAILED']:
            break
    return job

def get_transcript(job):
    if job['TranscriptionJob']['TranscriptionJobStatus'] == 'COMPLETED':
        transcript_uri = job['TranscriptionJob']['Transcript']['TranscriptFileUri']
        response = boto3.client('s3').get_object(Bucket=transcript_uri.split('/')[2], Key=transcript_uri.split('/')[3])
        transcript = response['Body'].read().decode('utf-8')
        return transcript
    else:
        return 'Transcription job failed'

if __name__ == '__main__':
    job_name = 'example_job_name'
    job = poll_transcription_job(job_name)
    transcript = get_transcript(job)
    print(transcript)
